mapper.select:
SELECT h.id, h.instance_id, h.calculation_version, h.calculation_type, h.calculation_status, h.input_data, h.output_data, h.error_message, h.execution_time, h.triggered_by, h.started_at, h.completed_at, h.created_at, i.instance_code, i.instance_name FROM soo_model_instance_calculation_history h LEFT JOIN soo_financial_model_instance i ON h.instance_id = i.id AND i.deleted = 0 WHERE 1=1
AND h.instance_id = #{instanceId}
AND h.calculation_type = #{calculationType}
AND h.calculation_status = #{calculationStatus}
ORDER BY h.started_at DESC
